import { z } from "zod";

/**
 * The board a model is allowed to reason about. Every field is generated by us,
 * never by the model: this is the whole answer to "the AI must see the board".
 */
export type GroundedView = {
  fen: string;
  sideToMove: "w" | "b";
  /** ASCII board with rank/file labels, so squares are named in prose too. */
  ascii: string;
  /** Legal moves as `SAN (e2e4)` — the only moves the model may pick. */
  legal: string[];
  /** Last three plies, oldest first. */
  history: string[];
  check: boolean;
};

export type LegalMove = { san: string; uci: string };

export type MoveChoice = { san: string; uci: string; comment?: string };

export type BrainResult =
  | { ok: true; move: MoveChoice; attempts: number }
  | { ok: false; reason: string; attempts: number; raw: string[] };

/** The one function the caller must supply: talk to the model and return text. */
export type ChatFn = (messages: { role: "system" | "user"; content: string }[], signal?: AbortSignal) => Promise<string>;

const Schema = z.object({ move: z.string().min(1), comment: z.string().optional() });

/**
 * Letters, not chess glyphs: a glyph carries no colour, so `♞` cannot say whose
 * knight it is. Upper case is white and lower case is black, which is the
 * convention every engine diagram and every model has already seen.
 */
export function asciiBoard(fen: string): string {
  const rows = fen.split(" ")[0]?.split("/") ?? [];
  const lines = rows.map((row, i) => {
    const cells: string[] = [];
    for (const ch of row) {
      if (ch >= "1" && ch <= "8") for (let n = 0; n < Number(ch); n++) cells.push(".");
      else cells.push(ch);
    }
    return `${8 - i} ${cells.join(" ")}`;
  });
  return [...lines, "  a b c d e f g h"].join("\n");
}

export function buildView(input: { fen: string; legal: LegalMove[]; history?: string[]; check?: boolean }): GroundedView {
  return {
    fen: input.fen,
    sideToMove: input.fen.split(" ")[1] === "b" ? "b" : "w",
    ascii: asciiBoard(input.fen),
    legal: input.legal.map((m) => `${m.san} (${m.uci})`),
    history: (input.history ?? []).slice(-3),
    check: input.check ?? false,
  };
}

export const SYSTEM_PROMPT = `You are playing chess. You will be given the position as FEN, an ASCII board, and the complete list of legal moves.
Rules you must follow:
- Choose exactly one move from the LEGAL MOVES list. Any other move is invalid and will be rejected.
- Reply with JSON only: {"move":"<SAN>","comment":"<one short sentence>"}
- Do not invent squares, pieces, or moves. If you are unsure, pick the move you understand best rather than inventing one.`;

export function userPrompt(v: GroundedView, mode: "opponent" | "coach"): string {
  return [
    `FEN: ${v.fen}`,
    `Side to move: ${v.sideToMove === "w" ? "white" : "black"}${v.check ? " (in check)" : ""}`,
    "",
    "Board (upper case = white, lower case = black):",
    v.ascii,
    "",
    v.history.length ? `Recent moves: ${v.history.join(" ")}` : "Recent moves: none",
    "",
    "LEGAL MOVES:",
    v.legal.join(", "),
    "",
    mode === "coach" ? "Suggest the strongest move and explain it in one sentence." : "Choose your move.",
  ].join("\n");
}

/** Accept SAN with or without the decorations models like to add. */
function canonical(text: string): string {
  return text
    .trim()
    .replace(/^[`'"\s]+|[`'"\s]+$/g, "")
    .replace(/^(\d+\.+\s*)/, "")
    .replace(/[+#!?]+$/, "")
    .trim();
}

function extract(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    // Models wrap JSON in prose or fences constantly; take the first object.
    const start = text.indexOf("{");
    const end = text.lastIndexOf("}");
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(text.slice(start, end + 1));
      } catch {
        return null;
      }
    }
    return null;
  }
}

/**
 * Grounding, enforced: a candidate counts only if it is one of the moves *we*
 * listed. Legality is not re-derived from the text, so a model that names a
 * plausible-but-absent move (a hallucinated knight) cannot reach the board.
 */
export function resolveChoice(text: string, legal: LegalMove[]): MoveChoice | null {
  const parsed = Schema.safeParse(extract(text));
  if (!parsed.success) return null;
  const want = canonical(parsed.data.move);
  const bySan = legal.find((m) => canonical(m.san) === want);
  if (bySan) return { san: bySan.san, uci: bySan.uci, comment: parsed.data.comment };
  const byUci = legal.find((m) => m.uci.toLowerCase() === want.toLowerCase());
  if (byUci) return { san: byUci.san, uci: byUci.uci, comment: parsed.data.comment };
  return null;
}

/** Undo `buildView`'s `SAN (uci)` decoration. */
function splitLegal(entry: string): LegalMove {
  const m = /^(.*)\s+\(([a-h][1-8][a-h][1-8][qrbn]?)\)$/.exec(entry);
  return m ? { san: m[1]!.trim(), uci: m[2]! } : { san: entry, uci: "" };
}

/**
 * One retry, then give up. The caller falls back to the engine rather than
 * letting a bad answer stall a game, and the reason is kept so `doctor`-style
 * output can show why the model is being ignored.
 */
export async function askForMove(
  view: GroundedView,
  chat: ChatFn,
  opts: { mode?: "opponent" | "coach"; timeoutMs?: number; attempts?: number } = {},
): Promise<BrainResult> {
  const mode = opts.mode ?? "opponent";
  const max = Math.max(1, opts.attempts ?? 2);
  const legal = view.legal.map(splitLegal);
  const raw: string[] = [];
  let last = "the model did not return a usable move";

  for (let attempt = 1; attempt <= max; attempt++) {
    const signal = opts.timeoutMs ? AbortSignal.timeout(opts.timeoutMs) : undefined;
    try {
      const text = await chat(
        [
          { role: "system", content: SYSTEM_PROMPT },
          { role: "user", content: userPrompt(view, mode) },
        ],
        signal,
      );
      raw.push(text.slice(0, 400));
      const choice = resolveChoice(text, legal);
      if (choice) return { ok: true, move: choice, attempts: attempt };
      last = "the model named a move that is not in the legal list";
    } catch (err) {
      last = err instanceof Error ? err.message : String(err);
    }
  }
  return { ok: false, reason: last, attempts: max, raw };
}
